SELECT id, service, log_ts, status_code, context, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['trace'], 'unknown') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs;
